import { api } from 'pages/APIs';
import { LocalStorage } from 'quasar';
import type { dynamicObj } from 'src/pages/assets';
import { userApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';
import { cacheDataAfterLogin } from 'src/utils/dataCache';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { isUndefinedOrNull, isObjectEmtpy } from 'src/utils/general';

const social_status_options = {
  '/register': 'register-',
  '/': 'login-',
} as dynamicObj;
const storage_name = 'after_login_route';

export default {
  methods: {
    getStatusByRoute(current_path: string) {
      let status = 'login';
      if (
        social_status_options.hasOwnProperty(current_path) &&
        social_status_options[current_path] !== ''
      ) {
        status = social_status_options[current_path];
      }
      return status;
    },

    setDashboardAsPath() {
      LocalStorage.set(storage_name, '/dashboard');
    },

    setScanAsPath() {
      LocalStorage.set(storage_name, '/directscan');
    },

    getPathFromStorage() {
      const login_path = LocalStorage.getItem(storage_name) as string;
      let path = login_path;
      if (
        !LocalStorage.has(storage_name) ||
        login_path === null ||
        login_path === ''
      ) {
        path = '/dashboard';
      }
      LocalStorage.remove(storage_name);
      return path;
    },

    async getPathRedirect() {
      const default_path = 'go_to_apps';

      try {
        const settings_store = useSettingStore();
        const USER_SELECTED_APPS =
          await settings_store.getSetting('USER_SELECTED_APPS');

        // no selected apps
        const selected_apps = JSON.parse(USER_SELECTED_APPS);

        if (this.onlyCurrentAppSelected(selected_apps, 'doc2scan')) {
          return 'go_to_scan';
        }

        if (this.onlyCurrentAppSelected(selected_apps, 'doc2')) {
          return 'go_to_dashboard';
        }

        if (this.onlyCurrentAppSelected(selected_apps, 'workflow')) {
          return 'go_to_workflow';
        }
      } catch (error: any) {
        logError(error);
      } finally {
      }

      return default_path;
    },

    savePath(error: any) {
      if (error === 'go_to_scan') {
        this.setScanAsPath();
      }
      if (error === 'go_to_dashboard') {
        this.setDashboardAsPath();
      }
    },

    onlyCurrentAppSelected(selected_apps: any, app_name: string) {
      if (isObjectEmtpy(selected_apps)) {
        return false;
      }

      if (
        selected_apps.hasOwnProperty(app_name) &&
        selected_apps[app_name] === true
      ) {
        return true;
      }
      return false;
    },

    isAnyAppSelected(selected_apps: any) {
      if (isObjectEmtpy(selected_apps)) {
        return false;
      }

      let is_any_app_selected = false;
      for (const [key, value] of Object.entries(selected_apps)) {
        if (value === true) {
          is_any_app_selected = true;
        }
      }
      return is_any_app_selected;
    },

    isOAuthLoginRoute(componenet_this: any) {
      if (componenet_this.$route.path == '/oauth/login') {
        return true;
      }
      return false;
    },

    async redirectForOAuthLogin() {
      const token = (await userApiService.getToken()).replace('Bearer ', '');
      const org_id = getUserDetailFromkey('org_id');
      const url =
        api.insight_url + '/sso/polydocs/' + org_id + '?code=' + token;
      window.open(url);
    },

    getLoginSource() {
      const login_source = LocalStorage.getItem('login_source') as string;
      if (!LocalStorage.has('login_source') || login_source === null) {
        return '';
      }
      return String(login_source.toLowerCase());
    },

    afterLoginRedirect(componenet_this: any) {
      try {
        cacheDataAfterLogin();

        if (this.isOAuthLoginRoute(componenet_this)) {
          this.redirectForOAuthLogin();
        }

        let redirectUrl = this.getPathFromStorage();

        if (
          componenet_this.$route.hasOwnProperty('query') &&
          componenet_this.$route.query.hasOwnProperty('redirect')
        ) {
          redirectUrl = componenet_this.$route.query.redirect;
        }
        componenet_this.$router.push(redirectUrl);
      } catch (error: any) {
        logError(error);
      } finally {
      }
    },

    async getSelectedApps() {
      const settings_store = useSettingStore();
      const USER_SELECTED_APPS =
        await settings_store.getSetting('USER_SELECTED_APPS');
      if (
        isUndefinedOrNull(USER_SELECTED_APPS) ||
        USER_SELECTED_APPS === undefined ||
        USER_SELECTED_APPS === '' ||
        isObjectEmtpy(USER_SELECTED_APPS)
      ) {
        return {};
      }
       
      return JSON.parse(USER_SELECTED_APPS);
    },

    async saveSelectedAppsInPreference(app_name: string, value: boolean) {
      try {
        const selected_apps = this.getSelectedApps();
        selected_apps[app_name] = value;
        const setting_name = 'USER_SELECTED_APPS';
        const setting_value = JSON.stringify(selected_apps);

        const settings_store = useSettingStore();
        await settings_store.updateSetting(setting_name, setting_value);
      } catch (error: any) {
        throw error;
      } finally {
      }
    },
  },
};
